from math import erf, exp, log, pi, sqrt

def Phi(z):
    return 0.5 * (1 + erf(z / sqrt(2)))

def phi(z):
    return exp(-z * z / 2) / sqrt(2 * pi)

def bs_call(S, K, r, sigma, T):
    d1 = (log(S / K) + (r + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    return S * Phi(d1) - K * exp(-r * T) * Phi(d1 - sigma * sqrt(T))

def skew_vol(K, atm, slope):
    """Vol at strike K: the at-the-money vol (at strike 100) plus
    slope for each point of strike."""
    return atm + slope * (K - 100)

def digital_call_skew(S, K, r, atm, slope, T):
    """exp(-rT) Phi(d2) minus vega times slope, using the vol at K.
    Vega is S phi(d1) sqrt(T) per 1.00 of vol."""
    sigma = skew_vol(K, atm, slope)
    d1 = (log(S / K) + (r + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    d2 = d1 - sigma * sqrt(T)
    vega = S * phi(d1) * sqrt(T)
    return exp(-r * T) * Phi(d2) - vega * slope

def digital_by_spread(S, K, r, atm, slope, T, h=0.01):
    """Tight call spread from K - h/2 to K + h/2, each priced at its
    own strike's vol, divided by h."""
    lo, hi = K - h / 2, K + h / 2
    c_lo = bs_call(S, lo, r, skew_vol(lo, atm, slope), T)
    c_hi = bs_call(S, hi, r, skew_vol(hi, atm, slope), T)
    return (c_lo - c_hi) / h
